import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Skills, Skillcap & Teachers","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/characters/skills.md","filePath":"en/guide/characters/skills.md"}'),s={name:"en/guide/characters/skills.md"};function r(l,e,o,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="skills-skillcap-teachers" tabindex="-1">Skills, Skillcap &amp; Teachers <a class="header-anchor" href="#skills-skillcap-teachers" aria-label="Permalink to &quot;Skills, Skillcap &amp; Teachers&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> These are intended changes, not confirmed live rules. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">full design specification</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Skills provide capability within a proposed shared budget of about 700 points / 100 per skill.</li><li>Teachers supply fundamentals at zero; starting competencies may already include them.</li><li>Useful early work and meaningful next steps matter; exact gains and teaching costs remain open.</li></ul><h2 id="capability-within-a-shared-budget" tabindex="-1">Capability within a shared budget <a class="header-anchor" href="#capability-within-a-shared-budget" aria-label="Permalink to &quot;Capability within a shared budget&quot;">​</a></h2><p>The current direction is approximately <strong>700 total skill points</strong> and <strong>100 normal maximum</strong>, with no ordinary 120 climb. These are design targets, not confirmed server settings. Investing deeply should give distinct capability while leaving room for useful supporting skills.</p><h2 id="useful-at-every-stage" tabindex="-1">Useful at every stage <a class="header-anchor" href="#useful-at-every-stage" aria-label="Permalink to &quot;Useful at every stage&quot;">​</a></h2><p>Novices should handle simple work consistently. Competent characters gain reliable basics; skilled characters contribute to groups; professionals tackle advanced situations; experts interpret more and work consistently; masters reach the top of technical proficiency. These are approximate bands, not a catalogue of hard unlocks.</p><p>Early gains should be fast, ordinary progression substantial, and the final approach to 100 slow and significant. Reaching relevant skills around 40–60 during the first day is an aspiration that depends on activity and build—not a promised timetable.</p><h2 id="learning-skills-and-finding-teachers" tabindex="-1">Learning skills and finding teachers <a class="header-anchor" href="#learning-skills-and-finding-teachers" aria-label="Permalink to &quot;Learning skills and finding teachers&quot;">​</a></h2><p>At exactly zero, a character generally needs fundamentals from a teacher, academy, guild, trainer or specialist. Instruction might bring skill to roughly 5–10 or otherwise unlock those fundamentals. Practice, exploration and use then continue learning. Starting competencies are an exception: <a href="/Syrolands-Public/en/guide/characters/character-creation.html">backgrounds</a> may already supply fundamentals around skill 20.</p><p>Costs, teacher availability and exact gain rates remain open. No teaching gate has been added to the running game by this documentation.</p><h2 id="know-what-training-offers" tabindex="-1">Know what training offers <a class="header-anchor" href="#know-what-training-offers" aria-label="Permalink to &quot;Know what training offers&quot;">​</a></h2><p>You should be able to see current capabilities and meaningful next steps. Routine low-difficulty work should not produce constant failures; higher skill expands the difficulty you can handle. This clarity does not reveal every hidden recipe, technique or secret interaction.</p><p><a href="/Syrolands-Public/en/guide/characters/progression.html">Character progression</a> · <a href="/Syrolands-Public/en/guide/characters/techniques.html">Learned techniques</a></p>',15)])])}const g=a(s,[["render",r]]);export{p as __pageData,g as default};
